import React, { useState, useEffect, useRef } from 'react';
import { io } from 'socket.io-client';

function LaptopWebcamFeed() {
  const containerRef = useRef(null);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isMinimized, setIsMinimized] = useState(false);

  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };

    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const toggleFullscreen = () => {
    if (!containerRef.current) return;

    if (!document.fullscreenElement) {
      containerRef.current.requestFullscreen().catch((err) => {
        console.error("Error entering fullscreen:", err);
      });
    } else {
      document.exitFullscreen().catch((err) => {
        console.error("Error exiting fullscreen:", err);
      });
    }
  };

  return (
    <div
      ref={containerRef}
      style={{
        position: 'relative',
        width: '100%',
        aspectRatio: isFullscreen ? 'unset' : '16 / 9',
        height: isFullscreen ? '100vh' : isMinimized ? '48px' : 'auto',
        backgroundColor: '#000',
        borderRadius: isFullscreen ? '0px' : '8px',
        overflow: 'hidden',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        transition: 'all 0.3s ease'
      }}
    >
      {/* Stream Video / Placeholder */}
      {!isMinimized ? (
        <img
          src="http://localhost:5001/video_feed"
          alt="Live AI Surveillance Stream"
          style={{ width: '100%', height: '100%', objectFit: 'contain', display: 'block' }}
          onError={(e) => {
            e.target.onerror = null;
            e.target.src = "https://via.placeholder.com/640x360?text=Start+detector.py+to+View+AI+Feed";
          }}
        />
      ) : (
        <div style={{ color: '#94a3b8', fontSize: '0.85rem', fontWeight: 'bold' }}>
          📹 Feed Minimized
        </div>
      )}

      {/* OVERLAY BUTTONS (FULLSCREEN & MINIMIZE) */}
      <div style={{ position: 'absolute', top: '10px', right: '10px', zIndex: 20, display: 'flex', gap: '6px' }}>
        {/* Fullscreen Button */}
        <button
          onClick={toggleFullscreen}
          title={isFullscreen ? "Exit Fullscreen" : "Fullscreen"}
          style={{
            background: 'rgba(15, 23, 42, 0.85)',
            color: '#ffffff',
            border: '1px solid rgba(255, 255, 255, 0.25)',
            borderRadius: '6px',
            padding: '6px 10px',
            fontSize: '0.85rem',
            fontWeight: '600',
            cursor: 'pointer',
            backdropFilter: 'blur(4px)',
            display: 'flex',
            alignItems: 'center',
            gap: '4px'
          }}
        >
          {isFullscreen ? '🗗 Minimize' : '⛶ Fullscreen'}
        </button>

        {/* Minimize / Expand Stream Button */}
        <button
          onClick={() => setIsMinimized(!isMinimized)}
          title={isMinimized ? "Expand Stream" : "Minimize Stream"}
          style={{
            background: 'rgba(15, 23, 42, 0.85)',
            color: '#ffffff',
            border: '1px solid rgba(255, 255, 255, 0.25)',
            borderRadius: '6px',
            padding: '6px 10px',
            fontSize: '0.85rem',
            fontWeight: '600',
            cursor: 'pointer',
            backdropFilter: 'blur(4px)'
          }}
        >
          {isMinimized ? '➕' : '➖'}
        </button>
      </div>
    </div>
  );
}

export default function Dashboard({ token }) {
  const [cameras, setCameras] = useState([]);
  const [userEmail, setUserEmail] = useState('');
  const [emailSavedMsg, setEmailSavedMsg] = useState('');
  const [, setEvidenceLogs] = useState([]);

  useEffect(() => {
    if ('Notification' in window && Notification.permission !== 'granted') {
      Notification.requestPermission();
    }

    // Fetch Cameras
    fetch('http://localhost:5000/api/cameras', {
      headers: { 'Authorization': `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => setCameras(Array.isArray(data) ? data : []))
      .catch(() => setCameras([]));

    // Fetch Settings
    fetch('http://localhost:5000/api/settings', {
      headers: { 'Authorization': `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => setUserEmail(data.email || ''))
      .catch(err => console.error(err));

    // Fetch Evidence Logs
    fetch('http://localhost:5000/api/evidence', {
      headers: { 'Authorization': `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => setEvidenceLogs(Array.isArray(data) ? data : []))
      .catch(() => setEvidenceLogs([]));

    // Socket.io Realtime Listener
    const socket = io('http://localhost:5000');
    socket.on('new-alert', (newLog) => {
      setEvidenceLogs(prev => [newLog, ...(Array.isArray(prev) ? prev : [])]);
    });

    return () => socket.disconnect();
  }, [token]);

  const handleSaveEmail = (e) => {
    e.preventDefault();
    fetch('http://localhost:5000/api/settings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
      body: JSON.stringify({ email: userEmail })
    }).then(() => {
      setEmailSavedMsg('Alert recipient email updated successfully!');
      setTimeout(() => setEmailSavedMsg(''), 3000);
    });
  };

  const handleDeleteCamera = (id) => {
    fetch(`http://localhost:5000/api/cameras/${id}`, {
      method: 'DELETE',
      headers: { 'Authorization': `Bearer ${token}` }
    }).then(() => {
      setCameras(prev => (Array.isArray(prev) ? prev.filter(c => c.id !== id) : []));
    });
  };

  const safeCameras = Array.isArray(cameras) ? cameras : [];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>

      {/* EMAIL NOTIFICATION CONFIGURATION */}
      <div className="card" style={{ background: '#1e293b', borderLeft: '4px solid #38bdf8', padding: '1.25rem', borderRadius: '10px' }}>
        <h3 style={{ margin: 0 }}>⚙️ Alert Notification Configuration</h3>
        <p style={{ color: '#94a3b8', fontSize: '0.9rem', margin: '0.5rem 0 1rem 0' }}>
          Recipient email for threat detection alerts and incident logs.
        </p>

        {emailSavedMsg && <div className="message-banner success">{emailSavedMsg}</div>}

        <form onSubmit={handleSaveEmail} style={{ display: 'flex', gap: '1rem', alignItems: 'center' }}>
          <div className="form-group" style={{ flex: 1, marginBottom: 0 }}>
            <input
              type="email"
              placeholder="admin@surveillance.com"
              value={userEmail}
              onChange={e => setUserEmail(e.target.value)}
              required
              style={{ width: '100%', padding: '0.65rem', borderRadius: '6px', border: '1px solid #334155', background: '#0f172a', color: '#fff' }}
            />
          </div>
          <button type="submit" className="btn-primary" style={{ width: 'auto', marginTop: 0, padding: '0.65rem 1.5rem', background: '#38bdf8', color: '#0f172a', fontWeight: 'bold', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>
            Save Settings
          </button>
        </form>
      </div>

      {/* STREAMS LIST */}
      <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
          <h2>Live Stream Feeds ({safeCameras.length})</h2>
          <span style={{ color: '#34d399', fontWeight: '600' }}>● AI Computer Vision Engine Active</span>
        </div>

        {safeCameras.length === 0 ? (
          <div className="card" style={{ textAlign: 'center', padding: '3rem', background: '#0f172a', borderRadius: '10px' }}>
            <p style={{ color: '#94a3b8' }}>No active camera streams configured.</p>
          </div>
        ) : (
          <div className="camera-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(420px, 1fr))', gap: '1.5rem' }}>
            {safeCameras.map((cam) => (
              <div key={cam.id} className="card camera-card" style={{ padding: '1.25rem', background: '#0f172a', borderRadius: '10px', border: '1px solid #1e293b' }}>

                {/* HEADER: TITLE + REMOVE CAMERA BUTTON */}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
                  <div>
                    <h3 style={{ fontSize: '1.1rem', margin: 0, color: '#f8fafc' }}>{cam.name}</h3>
                    <span style={{ fontSize: '0.8rem', color: '#94a3b8' }}>Zone: {cam.locationType}</span>
                  </div>

                  {/* REMOVE BUTTON */}
                  <button
                    onClick={() => handleDeleteCamera(cam.id)}
                    style={{
                      background: 'rgba(239, 68, 68, 0.15)',
                      color: '#f87171',
                      border: '1px solid #ef4444',
                      padding: '0.4rem 0.85rem',
                      borderRadius: '6px',
                      cursor: 'pointer',
                      fontSize: '0.85rem',
                      fontWeight: 'bold',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '0.3rem'
                    }}
                  >
                    🗑️ Remove
                  </button>
                </div>

                {/* CAMERA FEED WITH OVERLAY CONTROLS */}
                <div className="feed-box" style={{ padding: 0, overflow: 'hidden' }}>
                  {cam.rtspUrl === '0' ? (
                    <LaptopWebcamFeed />
                  ) : (
                    <div style={{ padding: '2rem', textAlign: 'center', color: '#94a3b8' }}>
                      RTSP Stream: {cam.rtspUrl}
                    </div>
                  )}
                </div>

              </div>
            ))}
          </div>
        )}
      </div>

    </div>
  );
}
